import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"天風姤","description":"周易折中 - 天風姤","frontmatter":{"title":"天風姤","description":"周易折中 - 天風姤"},"headers":[],"relativePath":"classics/zhezhong/050.md","filePath":"classics/zhezhong/050.md"}'),h={name:"classics/zhezhong/050.md"};function n(d,a,p,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="天風姤" tabindex="-1">天風姤 <a class="header-anchor" href="#天風姤" aria-label="Permalink to “天風姤”">​</a></h1><h3 id="《程傳》" tabindex="-1">《程傳》 <a class="header-anchor" href="#《程傳》" aria-label="Permalink to “《程傳》”">​</a></h3><p>〈姤序卦〉：“夬，決也。決必冇遇，故受之以姤。姤，遇也。決判也，物之決判則有遇合，本合則何遇？姤所以次夬也。為卦幹上巽下，以二體言之，風行天下，天之下者萬物也，風之行無不經觸，乃遇之象，又一陰始生於下，陰與陽遇也，故為姤。”</p><p>姤：女壯，勿用取女</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>姤，遇也。決盡則為純幹，四月之卦。至姤然後一陰可見，而為五月之卦。以其本非所望，而卒然值之，如不期而遇者，故為遇。遇已非正，又一陰而遇五陽，則女德不貞而壯之甚也。取以自配，必害乎陽，故其象佔如此。</p><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>一陰始生，自是而長，漸以盛大，是女之將長壯也。陰長則陽消，女壯則男弱，故戒勿用取如是之女。取女者，欲其柔和順從以成家道，姤乃方進之陰，漸壯而敵陽者，是以不可取也。女漸壯則失男女之正，家道敗矣。姤雖一陰甚微，然有漸壯之道，所以戒也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>孔氏穎達曰 ：姤，遇也。此卦一柔而遇五剛，故名為姤。施之於人，則是一女而遇五男，為壯至甚。故戒之曰：“此女壯甚，勿用取此女也。”</li></ul><p>孔氏穎達曰 ：姤，遇也。此卦一柔而遇五剛，故名為姤。施之於人，則是一女而遇五男，為壯至甚。故戒之曰：“此女壯甚，勿用取此女也。”</p><ul><li>郭氏雍曰 ：陽至四五而後言壯，姤一陰方長即為壯者，亦見君子小人之情不同也。</li></ul><p>郭氏雍曰 ：陽至四五而後言壯，姤一陰方長即為壯者，亦見君子小人之情不同也。</p><ul><li>馮氏椅曰 ：古文“姤”作“遘”，遇也，亦婚媾也。以女遇男為象。王洙《易》改為今文為“姤”，雜卦猶是古文，鄭本同。</li></ul><p>馮氏椅曰 ：古文“姤”作“遘”，遇也，亦婚媾也。以女遇男為象。王洙《易》改為今文為“姤”，雜卦猶是古文，鄭本同。</p><ul><li>胡氏炳文曰 ：女壯，諸家皆以為一陰有將盛之漸，本義以為一陰當五陽已有女壯之象。</li></ul><p>胡氏炳文曰 ：女壯，諸家皆以為一陰有將盛之漸，本義以為一陰當五陽已有女壯之象。</p><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>女壯之義，非以一陰始生於下為壯，亦非以一陰獨當五陽為壯。蓋卦以陰為主，陰而為主，即是壯也。</p><p>此處AI有獨到的見解：姤卦一陰初生，雖未盛大，但已顯現其為主之勢，故曰女壯。此時若取其女，則必害乎陽，因此戒之曰“勿用取女”。這一解釋強調了陰為主即為壯的觀點，與傳統解釋有所不同，但亦有其獨特的見解和邏輯。</p><p>象曰：天下有風姤，後以施命誥四方</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>風行天下，無所不周，為君後者觀其周遍之象，以施其命令，周誥四方也。風行地上與天下有風，皆為周遍庶物之象。而行於地上，遍觸萬物，則為觀，經歷觀省之象也；行於天下，周遍四方，則為姤，施發命令之象也。諸象或稱先王，或稱後，或稱君子大人。稱先王者，先王所以立法制、建國作樂、省方敕法、閉關育物、享帝皆是也。稱後者，后王之所為也，財成天地之道，施命誥四方是也。君子則上下之通稱，大人者王公之通稱。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li>龔氏煥曰：天下有風姤與風行地上觀相似，故在姤則曰施命誥四方，在觀則曰省方觀民設教。曰施、曰誥，自上而下，天下有風之象也；曰省、曰觀，周曆遍覽，風行地上之象也。案巽之申命因有積弊而振飭之也，姤之施命與巽正同，蓋在三畫之卦為巽者，在六畫之卦即為姤也。施命、申命，所以消隠慝、除積弊，法風之吹散伏陰也。</li></ul><p>彖曰：姤，遇也，柔遇剛也</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>釋卦名。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>姤之義遇也。卦之為姤，以柔遇剛也。一陰方生，始與陽相遇也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>趙氏汝梅曰 ：柔遇剛者，明非剛遇柔也。</p></li><li><p>林氏希元曰 ：依本義是陽遇陰，依彖傳是陰遇陽。彖傳乃本義以一陰而遇五陽，意蓋彖傳是為下文“勿用取女，不可與長”而設也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>柔遇剛者，以柔為主也。如臣之專制，如牝之司晨，得不謂壯乎？故不復釋“女壯”，而直釋“勿用取女”之義。</p><p>勿用取女，不可與長也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦辭。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>一陰既生，漸長而盛。陰盛則陽衰矣。取女者欲長久而成家也，此漸盛之陰將消勝於陽，不可與之長久也。凡女子、小人、夷狄，勢苟漸盛，何可與久也？故戒勿用取如是之女。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏康成曰 ：一陰承五陽，苟相遇耳，非禮之正。女壯如是，故不可娶。</p></li><li><p>王氏肅曰 ：女不可娶，以其不正，不可與長久也。</p></li><li><p>蘇氏軾曰 ：姤者，所遇而合無適應之謂也。故其女不可與長。</p></li><li><p>李氏舜臣曰 ：以一陰遇五陽，女下於男，有女不正之象，故曰“勿用取女”。鹹所以取女吉者，以男下女，得婚姻正禮故也。若蒙之六三以陰而先求陽，其行不順，故亦曰“勿用取女”。</p></li></ul><p>天地相遇，品物鹹章也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>以卦體言。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>陰始生於下與陽相遇，天地相遇也。陰陽不相交遇則萬物不生，天地相遇則化育庶類，品物鹹章，萬物章明也。</p><p>剛遇中正，天下大行也</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>指九五。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>以卦才言也。五與二皆以陽剛居中與正以中正相遇也。君得剛中之臣，臣遇中正之君，君臣以剛陽遇中正，其道可以大行於天下矣。</p><p>姤之時義大矣哉</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>幾㣲之際，聖人所謹。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>贊姤之時與姤之義至大也。天地不相遇則萬物不生，君臣不相遇則政治不興，聖賢不相遇則道德不亨，事物不相遇則功用不成。姤之時與義皆甚大也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類 ：問“姤之時義大矣哉”，本義雲“幾㣲之際，聖人所謹”，與伊川之說不同何也？曰上面說“天地相遇”至“天下大行也”，而不好之漸已生於微矣，故當謹於此。</p></li><li><p>吳氏曰慎曰 ：姤為陰遇陽之卦，陰陽有當遇者，如天地相遇及君臣夫婦之類，是不能相無者；有遇而當制者，如“勿用取女”及小人妄念之類，是不容並立者。時義大矣哉，程傳重“遇”字，專以遇之善者言；本義重“制”字，專以遇之不善者言。竊意此語總承上文兩端而言可也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>必如天地之相遇而後品物鹹章也，必如此卦以群剛遇中正之君，然後天下大行也。苟天地之相遇而有陰邪幹於其間，君臣之相遇而有宵類介乎其側，則在天地為伏陰，在國家為隠慝，而有女壯之象矣。</p><p>/books/106/44/1.html</p><p>初六 繫於金柅，貞吉；有攸往，見兇。羸豕孚蹢躅</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>柅，所以止車，以金為之，其剛可知。一陰始生，靜正則吉，往進則兇。故以二義戒小人，使不害於君子，則有吉而無兇。然其勢不可止也，故以“羸豕孚蹢躅”曉君子，使深為之備雲。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>姤，陰始生而將長之卦。一陰生則長而漸盛，陰長則陽消，小人道長也。制之當於其微而未盛之時。柅，止車之物，金為之，堅強之至也。止之以金柅而又系之，止之固也。固止使不得進，則陽剛貞正之道吉也。使之進往，則漸盛而害於陽，是見兇也。“羸豕孚蹢躅”，聖人重為之戒，言陰雖甚微，不可忽也。豕，陰躁之物，故以為況。羸弱之豕雖未能強猛，然其中心在乎蹢躅（跳躑）。陰微而在下，可謂羸矣，然其中心常在乎消陽也。君子小人異道，小人雖微弱之時，未嘗無害君子之心。防於微，則無能為矣。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>丘氏富國曰 ：姤之所以為姤者，在此一爻。一陰始生，非以金柅系之，則柔道何所牽制而不敢進？系之所以防之也。</li></ul><p>丘氏富國曰 ：姤之所以為姤者，在此一爻。一陰始生，非以金柅系之，則柔道何所牽制而不敢進？系之所以防之也。</p><ul><li>胡氏炳文曰 ：彖總一卦而言，則以一陰而當五陽，故於女為壯。爻指一畫而言，五陽之下一陰甚微，故於豕為羸。壯可畏也，羸不可忽也。</li></ul><p>胡氏炳文曰 ：彖總一卦而言，則以一陰而當五陽，故於女為壯。爻指一畫而言，五陽之下一陰甚微，故於豕為羸。壯可畏也，羸不可忽也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>一陰窮於上，眾以為無兇矣，而曰“終有兇”，防其後之辭也。一陰伏於下，眾未覺其兇矣，而曰“有攸往，見兇”，察於先之辭也。陰陽消息，循環無端，能察於先即所以防其後，能防其後即所以察於先也。</p><p>象曰：繫於金柅，柔道牽也</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>牽，進也。以其進，故止之。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>牽者，引而進也。陰始生而漸進，柔道方牽也。擊之於金柅，所以止其進也。不使進，則不能消正道，乃貞吉也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：柔道牽者，陰柔之道必須有所牽繫也。</p></li><li><p>鄭氏汝諧曰：此羸豕也，力雖微而其志則蹢躅，惟信其蹢躅，則不可不有所牽制，故曰柔道牽也。</p></li><li><p>趙氏汝梅曰：姤之初言系、言牽，惡陰之長而止之也。</p></li></ul><p>九二：包有魚，無咎，不利賓</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>魚，陰物。二與初遇，為“包有魚”之象。然制之在已，故猶可以無咎。若不制而使遇於眾，則其為害廣矣。故其象佔如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>姤，遇也。二與初密比相遇者也。在他卦則初正應於四，在姤則以遇為重。相遇之道，主於專一。二之剛中遇初，固以誠然。初之陰柔，群陽在上而又有所應者，其志所求也。陰柔之質，鮮克貞固。二之於初，難得其誠心矣。所遇不得其誠心，遇道之乖也。包者，苴裹也。魚，陰物之美者。陽之於陰，其所悅美，故取魚象。二於初，若能固畜之如包苴之有魚，則於遇為無咎矣。賓，外來者也。不利賓，包苴之魚豈能及賓？謂不可更及外人也。遇道當專一，二則雜矣。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>陸氏希聲曰 ：不正之陰與剛中之二相比，能包而有之，使其邪不及於外。</li></ul><p>陸氏希聲曰 ：不正之陰與剛中之二相比，能包而有之，使其邪不及於外。</p><ul><li>李氏開曰 ：剝之貫魚，姤之包有魚，皆能制陰者也。</li></ul><p>李氏開曰 ：剝之貫魚，姤之包有魚，皆能制陰者也。</p><ul><li>胡氏炳文曰 ：包如包苴之包，容之於內而制之，使不得逸於外也。</li></ul><p>胡氏炳文曰 ：包如包苴之包，容之於內而制之，使不得逸於外也。</p><ul><li>何氏楷曰 ：“包”字與“系豕”、“包瓜”同意。古之小人所以亂天下者，往往君子激之也。二曰“包有魚”，則不視小人為異類而直以兼容之量包之。既下邇之使近，亦不激之使無所容，其何咎焉。</li></ul><p>何氏楷曰 ：“包”字與“系豕”、“包瓜”同意。古之小人所以亂天下者，往往君子激之也。二曰“包有魚”，則不視小人為異類而直以兼容之量包之。既下邇之使近，亦不激之使無所容，其何咎焉。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>制陰之義，不取諸九四之相應而取諸九二之相比者，陰陽主卦皆以近比者為親切而處之，又有中有不中焉。故復六四之獨復，亦不如六二休復之為美也。夬五近上，則有莧陸之嫌；姤二比初，獨不以陰邪為累乎？曰：夬之陰，其勢極矣，如病之既劇，如亂之已成，非有以除去之不可。姤則陰始生也，如病將發，如亂初萌，豫防而早冶之，則不至於盛長矣。觀乎“不利賓”之戒，未嘗不以陰邪之漸馴為諄諄也。《詩》雲：“敝笱在梁，其魚魴鰥。齊子歸止，其從如雲。”是不能制之而使及賓之驗矣。</p><p>象曰：包有魚，義不及賓也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>二之遇初，不可使有二於外，當如包苴之有魚，包苴之魚，義不及於賓客也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>吳氏曰愼曰：九二既包有魚，則當盡其防制之責，以義言之，不可使遇於賓也。若不制而使遇於賓，則失其義矣。</li></ul><p>九三：臀無膚，其行次且，厲無大咎</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>九三過剛不中，下不遇於初，上無應於上，居則不安，行則不進。故其象佔如此。然既無所遇，則無陰邪之傷，故雖危厲而無大咎也。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>二與初既相遇，三說初而密比於二，非所安也，又為二所忌惡。其居不安，若臀之無膚也。處既不安，則當去之。而居姤之時，志求乎遇，一陰在下是所欲也。故處雖不安，而其行則又次且也（次且，進難之狀，謂不能遽舍也）。然三剛正而處巽，有不終迷之義。若知其不正而懷危懼，不敢妄動，則可以無大咎也。非義求遇，固已有咎矣，知危而止，則不至於大也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>李氏簡曰 ：居則臀在下，故《困》初六言臀；行則臀在中，故《夬》《姤》三四言臀。</li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>臀無膚之義與夬四同。其行次且，志欲制陰也。非其位任而欲制之，有危道焉。然於義則無咎。</p><p>象曰：其行次且，行未牽也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>其始志在求遇於初，故其行遲遲，未牽不促其行也。既知危而改之，故未至於大咎也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>郭氏雍曰：無膚次且之厲，蓋未嘗牽勉而妄行焉，是以至此。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>易中言“牽”者，自小畜至此，皆當為牽制之義。</p><p>九四：包無魚，起兇</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>初六正應已遇於二而不及於己，故其象佔如此。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>包者，所裹畜也；魚，所美也。四與初為正應，當相遇者也。而初已遇於二矣，失其所遇，猶包之無魚，亡其所有也。四當姤遇之時，居上位而失其下，下之離由已之失徳也。四之失者，不中正也。以不中正而失其民，所以兇也。曰：“初之從二以比近也，豈四之罪乎？”曰：“在四而言，義當有咎。不能保其下，由失道也。豈有上不失道而下離者乎？”遇之道，君臣、民主、夫婦、朋友皆在焉。四以下睽，故主民而言。為上而下離，必有兇變起者，將生之謂。民心既離，難將作矣。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>吳氏曰 、 愼曰 ：九三以不遇陰而無大咎，上九以不遇陰而無咎，四則包無魚起兇，何也？蓋初六本其正應，當遇而不遇故也。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>四與初正應，當制陰之任者也。然不能制之，而為“包無魚”之象。何也？曰：此與夬之九三同，當決陰制陰之任，而德非中正。故一則剛壯而懷慍怒，一則疾惡而胥絕遠，無包容之量，無制服之方。故以是爻德而適犯卦義，“取女”之戒，則其起兇宜矣。《書》曰：“寛而有制，有容德乃大。”又曰：“爾無忿疾於頑。”是“包有魚”、“無魚”之所由分也。</p><p>象曰：無魚之兇，遠民也</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>民之去已，猶已遠之。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>下之離，由已致之。遠民者，已遠之也。為上者有以使之離也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>餘氏本曰：言其使民失道，無以結民之心，致民之去，由已之遠乎民也。</li></ul><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>九四因與陰相應，故惡而欲遠之，正如夬三“壯於頄”之意。徒欲遠之而不能容之制之，此所以“包無魚”也。君子之於小人也，惟其能容之，是以能制之。不能容之，則彼自絕矣。欲以力制，不亦難乎？書曰“民可近不可下”，此之謂也。</p><p>九五：以杞包瓜，含章有隕自天</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>瓜，陰物之在下者，甘美而善潰。杞，高大堅實之木也。五以陽剛中正主卦於上，而下防始生必潰之陰，其象如此。然陰陽迭勝，時運之常。若能含晦章美，靜以制之，則可以回造化矣。有隕自天，本無而倏有之象也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>九五下亦無應，非有遇也。然得遇之道，故終必有遇。夫上下之遇，由相求也。杞，高木而葉大，處高體大而可以包物者。杞也，美實之在下者瓜也，美而居下者側微之賢之象也。九五尊居君位，而下求賢才，以至高而求至下，猶以杞葉而包瓜，能自降屈如此。又其內蘊中正之德，充實章美。人君如是，則無有不遇所求者也。雖屈己求賢，若其德不正，賢者不屑也。故必含蓄章美，內積至誠，則有隕自天矣。猶雲自天而降，言必得之也。自古人君至誠降屈，以中正之道求天下之賢，未有不遇者也。高宗感於夢寐，文王遇於漁釣，皆由是道也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰 ：魚與瓜皆陰物。二與初遇，故“包有魚”。五與初無相遇之道，猶以高大之杞而包在地之瓜也。然瓜雖始生而必潰，九五陽剛中正，能含晦章美，靜以待之。是雖陰陽消長，時運之常，而造化未有不可回者。姤其將可轉而為復乎？</li></ul><p>胡氏炳文曰 ：魚與瓜皆陰物。二與初遇，故“包有魚”。五與初無相遇之道，猶以高大之杞而包在地之瓜也。然瓜雖始生而必潰，九五陽剛中正，能含晦章美，靜以待之。是雖陰陽消長，時運之常，而造化未有不可回者。姤其將可轉而為復乎？</p><ul><li>俞氏琰曰 ：含即包之謂，其初含蓄不露。一旦瓜熟蒂脫，自杞墜地，故曰“含章有隕自天”。</li></ul><p>俞氏琰曰 ：含即包之謂，其初含蓄不露。一旦瓜熟蒂脫，自杞墜地，故曰“含章有隕自天”。</p><ul><li>林氏希元曰 ：含章不是全無所事，是用意周密，不動聲色而自有以消患於方萌也。</li></ul><p>林氏希元曰 ：含章不是全無所事，是用意周密，不動聲色而自有以消患於方萌也。</p><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>五為卦主，而與陰無比應，得卦“勿用取女”之義也。夫與陰雖無比應，而為卦主，則有制陰之任焉。故極言脩徳迴天之道。</p><p>象曰：九五含章中正也，有隕自天，志不捨命也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>所謂含章，謂其含蘊中正之德也。德充實則成章而有輝光。命，天理也；舍，違也。至誠中正，屈已求賢，存志合於天理，所以有隕自天，必得之矣。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘇氏軾曰：陰長而消陽，天之命也，有以勝之；人之志也，君子不以命廢志。故九五之志堅，則必有自天而隕者。言人之至者，天不能勝也。</p></li><li><p>楊氏啟新曰：陰陽迭勝，天運自然。而心心念念不舍天命，以靜制之，此所以挽回造化也。</p></li></ul><h3 id="案-10" tabindex="-1">案 <a class="header-anchor" href="#案-10" aria-label="Permalink to “案”">​</a></h3><p>詩云“桑之落矣，其黃而隕”，故有隕自天，謂天時既至而瓜隕也。雖天命之必然，亦由君子積誠脩德與之符會。故曰“志不捨命”。</p><p>上九：姤其角，吝無咎</p><h3 id="本義-13" tabindex="-1">本義 <a class="header-anchor" href="#本義-13" aria-label="Permalink to “本義”">​</a></h3><p>角，剛乎上者也。上九以剛居上而無位，不得其遇，故其象佔與九三類。</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>至剛而在最上者，角也。九以剛居上，故以角為象。人之相遇，由降屈以相從，和順以相接，故能合也。上九高亢而剛極，人誰與之？以此求遇，固可吝也已。則如是，人之遠之，非他人之罪也，由己致之，故無所歸咎。</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>徐氏幾曰 ：上九處姤之窮，與初無遇，雖吝，然亦無咎。陰不必遇也。</li></ul><p>徐氏幾曰 ：上九處姤之窮，與初無遇，雖吝，然亦無咎。陰不必遇也。</p><ul><li>胡氏炳文曰 ：九三以剛居下卦之上，於初陰無所遇，故雖厲而無大咎。上九以剛居上卦之上，於初陰亦不得其遇，故雖吝而亦無咎。遇本非正，不遇不足為咎也。</li></ul><p>胡氏炳文曰 ：九三以剛居下卦之上，於初陰無所遇，故雖厲而無大咎。上九以剛居上卦之上，於初陰亦不得其遇，故雖吝而亦無咎。遇本非正，不遇不足為咎也。</p><h3 id="案-11" tabindex="-1">案 <a class="header-anchor" href="#案-11" aria-label="Permalink to “案”">​</a></h3><p>此爻亦與夬初反對，皆與陰絕遠者也。不與陰遇，不能制陰，故可吝。然非其事任也，故無咎。此如避世之士，不能救時，而亦身不與亂者也。</p><p>象曰：姤其角，上窮吝也</p><h3 id="程傳-18" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-18" aria-label="Permalink to “程傳”">​</a></h3><p>既處窮上，剛亦極矣，是上窮而致吝也。以剛極居高而求遇，不亦難乎？</p><h3 id="案-12" tabindex="-1">案 <a class="header-anchor" href="#案-12" aria-label="Permalink to “案”">​</a></h3><p>不與陰遇，雖無咎，然君子終以不能濟時為可羞。為其身在事外，所處之窮故爾。</p>',173)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
